import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Future combat directions","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/future-directions.md","filePath":"en/game-design/combat/future-directions.md"}'),i={name:"en/game-design/combat/future-directions.md"};function s(r,e,d,c,l,m){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="future-combat-directions" tabindex="-1">Future combat directions <a class="header-anchor" href="#future-combat-directions" aria-label="Permalink to &quot;Future combat directions&quot;">​</a></h1><p><strong>Status: Proposed / Unresolved. Implementation: not present; outside Slice 0.</strong></p><p>Candidate techniques include precise/heavy attacks, feints, defensive responses, disarm, sweep and quick attacks. Stamina is a possible commitment resource; this is not automatic adoption of AOS mana abilities. Tactics may reveal openings that modify scheduled opportunities rather than grant free swings. Held swings and stances remain exploratory.</p><p>Cleave/propagation may apply bounded secondary local effects to related regions. Great axes, warhammers, two-handed swords and spears can have different roles; the <code>TwoHanded</code> slot alone must not enable the same effect. No adjacency graph, probabilities, mitigation order or region cap is accepted yet. Secondary local updates must not duplicate full hit checks, global damage, procs or equipment wear.</p><p>Persistence, healing, creature profiles, native illustrated assessment, final skill formulas and alternate animation pipelines remain separate proposals. The body primitive may later accept multiple bounded updates, but that seam is not an implementation of cleave.</p><p><strong>Gap:</strong> first obtain Slice 0 observations; do not convert this candidate list into an approved delivery schedule.</p><h2 id="proposed-localized-magic" tabindex="-1">Proposed localized magic <a class="header-anchor" href="#proposed-localized-magic" aria-label="Permalink to &quot;Proposed localized magic&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/magic.html#localized-magic-and-injury">Magic redesign v0.1</a> adds future spell-specific impact profiles, focused anatomical intent and injury/concentration interactions. Multi-region magic and casting penalties need their own contracts; they do not inherit melee tuning automatically or expand the authorized Slice 0 scope.</p><h2 id="combat-foundation-ownership" tabindex="-1">Combat foundation ownership <a class="header-anchor" href="#combat-foundation-ownership" aria-label="Permalink to &quot;Combat foundation ownership&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">Weapons</a>, <a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">armor</a> and <a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html">stamina/input</a> expand related proposals. The manual-input conflict and <a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">open decisions</a> remain unresolved; this batch does not approve or implement the advanced mechanics above.</p>',10)])])}const h=a(i,[["render",s]]);export{u as __pageData,h as default};
